import re

def parse_grid_raw(text):
    """Parse grid from space-separated string rows"""
    lines = text.strip().split('\n')
    grid = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        grid.append([int(x) for x in line.split()])
    return grid

