def transform_grid_v3(grid):
    """Transform based on correct pattern analysis"""
    import copy
    result = [[0] * len(grid[0]) for _ in range(len(grid))]

    # Find all 3s
    threes = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 3:
                threes.append((r, c))

    for r3, c3 in threes:
        n_rows, n_cols = len(grid), len(grid[0])

        # Row r3-2: 6s at cols c3-2 to c3+2
        if r3 - 2 >= 0:
            for c in range(c3 - 2, c3 + 3):
                if 0 <= c < n_cols:
                    result[r3 - 2][c] = 6

        # Row r3-1: 1 at c3-2, c3+2; 6 at c3
        if r3 - 1 >= 0:
            if c3 - 2 >= 0:
                result[r3 - 1][c3 - 2] = 1
            if c3 + 2 < n_cols:
                result[r3 - 1][c3 + 2] = 1
            if 0 <= c3 < n_cols:
                result[r3 - 1][c3] = 6

        # Row r3: 1 at c3-2, c3+2; 3 at c3
        if 0 <= r3 < n_rows:
            if c3 - 2 >= 0:
                result[r3][c3 - 2] = 1
            if c3 + 2 < n_cols:
                result[r3][c3 + 2] = 1
            # Keep original 3

        # Row r3+1: 1 at c3-2, c3+2 only
        if r3 + 1 < n_rows:
            if c3 - 2 >= 0:
                result[r3 + 1][c3 - 2] = 1
            if c3 + 2 < n_cols:
                result[r3 + 1][c3 + 2] = 1

        # Row r3+2: 1 at c3-2, c3+2; 7s at c3-2 to c3+2
        if r3 + 2 < n_rows:
            # 1s at sides, but only at immediate columns (not extended)
            c_left = c3 - 2
            c_right = c3 + 2
            # Put 1 at sides but don't overwrite 7s in middle
            if c_left >= 0 and c_left != c3 - 2:  # Not needed since these are the edge cols
                result[r3 + 2][c_left] = 1
            if c_right < n_cols and c_right != c3 + 2:
                result[r3 + 2][c_right] = 1

            # 7s at c3-2 to c3+2, putting 1s at outer edges
            for c in range(0, c3 - 2):  # Left extension
                result[r3 + 2][c] = 1
            for c in range(c3 - 2, c3 + 3):  # 7s in middle
                if 0 <= c < n_cols:
                    result[r3 + 2][c] = 7
            for c in range(c3 + 3, n_cols):  # Right extension
                result[r3 + 2][c] = 1

    return result

